        opacity: 0.35,
        duration: 0.6,
        repeat: -1,
        yoyo: true,
        ease: "sine.inOut",
      });
      return () => gsap.ticker.remove(paint);
    },
    {
      scope: rootRef,
      dependencies: [phase, reduced, demo],
      revertOnUpdate: true,
    },
